import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices } from '../src/reports.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty list for empty invoices', () => {
  const r = overdueInvoices([], '2026-10-31');
  assert.deepEqual(r, []);
});

test('overdueInvoices excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const invoices = [inv];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const paid = recordPayment(issued, { amount: 48854, date: '2026-10-15' }).value;

  const invoices = [paid];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 0);
});

test('overdueInvoices includes issued invoices with dueDate before asOf', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  assert.equal(r[0].number, 'INV-2026-0001');
  assert.equal(r[0].customerId, 'C-001');
  assert.equal(r[0].dueDate, '2026-11-06');
  assert.equal(r[0].due, 48854);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial = recordPayment(issued, { amount: 10000, date: '2026-10-15' }).value;

  const invoices = [partial];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  assert.equal(r[0].due, 38854);
});

test('overdueInvoices excludes invoices with dueDate equal to asOf', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = overdueInvoices(invoices, issued.dueDate);
  assert.equal(r.length, 0);
});

test('overdueInvoices excludes invoices with dueDate after asOf', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-11-05');
  assert.equal(r.length, 0);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // dueDate is 2026-11-06, asOf is 2026-11-20
  // daysOverdue = 14

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-11-20');
  assert.equal(r.length, 1);
  assert.equal(r[0].daysOverdue, 14);
});

test('overdueInvoices sorts by daysOverdue descending (most overdue first)', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2026-0001', 'INV-2026-0002']).value;

  const invoices = [issued2, issued1, issued3];
  const r = overdueInvoices(invoices, '2026-11-20');
  assert.equal(r.length, 3);
  assert.ok(r[0].daysOverdue >= r[1].daysOverdue);
  assert.ok(r[1].daysOverdue >= r[2].daysOverdue);
});

test('overdueInvoices returns empty list when no invoices are overdue', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-16',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const invoices = [issued1, issued2];
  const r = overdueInvoices(invoices, '2026-10-20');
  assert.equal(r.length, 0);
});

test('overdueInvoices filters by customerId in results', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const invoices = [issued1, issued2];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 2);
  const c001 = r.find(inv => inv.customerId === 'C-001');
  const c002 = r.find(inv => inv.customerId === 'C-002');
  assert.ok(c001);
  assert.ok(c002);
});

test('overdueInvoices handles invoices with vouchers', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const withVoucher = applyVoucher(inv, { code: 'PROMO', amount: 5000 }).value;
  const issued = issueInvoice(withVoucher, []).value;

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  // Total after voucher: 48854 - 5000 = 43854
  assert.equal(r[0].due, 43854);
});

test('overdueInvoices calculates due correctly for partially paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial = recordPayment(issued, { amount: 20000, date: '2026-10-15' }).value;

  const invoices = [partial];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  assert.equal(r[0].due, 28854);
});

test('overdueInvoices handles multiple payments on single invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial1 = recordPayment(issued, { amount: 10000, date: '2026-10-15' }).value;
  const partial2 = recordPayment(partial1, { amount: 15000, date: '2026-10-20' }).value;

  const invoices = [partial2];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  assert.equal(r[0].due, 23854);
});

test('overdueInvoices includes invoice number in results', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  assert.equal(r[0].number, 'INV-2026-0001');
});

test('overdueInvoices includes dueDate in results', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  assert.equal(r[0].dueDate, '2026-09-15');
});

test('overdueInvoices handles complex invoice with multiple lines', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial = recordPayment(issued, { amount: 50000, date: '2026-09-15' }).value;

  const invoices = [partial];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  assert.ok(r[0].due > 0);
  assert.ok(r[0].daysOverdue > 0);
});

test('overdueInvoices works with various payment terms', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2026-0001', 'INV-2026-0002']).value;

  const invoices = [issued1, issued2, issued3];
  const r = overdueInvoices(invoices, '2026-11-15');
  // NET14: due 2026-10-15 (31 days overdue)
  // NET30: due 2026-11-06 (9 days overdue)
  // EOM: due 2026-10-31 (15 days overdue)
  assert.equal(r.length, 3);
  assert.equal(r[0].daysOverdue, 31); // Most overdue
  assert.equal(r[1].daysOverdue, 15);
  assert.equal(r[2].daysOverdue, 9); // Least overdue
});

test('overdueInvoices excludes invoices without number field', () => {
  const inv = {
    customerId: 'C-001',
    issueDate: '2026-09-01',
    status: 'issued',
    dueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 5 }],
  };

  const invoices = [inv];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 0);
});

test('overdueInvoices handles mix of draft, issued, partially_paid, and paid invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv2, []).value;

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2026-0001']).value;
  const partial = recordPayment(issued3, { amount: 10000, date: '2026-09-15' }).value;

  const inv4 = createInvoice({
    customerId: 'C-004',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued4 = issueInvoice(inv4, ['INV-2026-0001', 'INV-2026-0002']).value;
  const paid = recordPayment(issued4, { amount: 48854, date: '2026-09-15' }).value;

  const invoices = [draft, issued, partial, paid];
  const r = overdueInvoices(invoices, '2026-10-31');
  // Should include: issued and partial, but not draft and paid
  assert.equal(r.length, 2);
  const numbers = r.map(inv => inv.number);
  assert.ok(numbers.includes('INV-2026-0002'));
  assert.ok(numbers.includes('INV-2026-0003'));
});

test('overdueInvoices calculates correct daysOverdue across month boundaries', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;
  // dueDate: 2026-10-15

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-11-15');
  assert.equal(r.length, 1);
  // From 2026-10-15 to 2026-11-15 = 31 days
  assert.equal(r[0].daysOverdue, 31);
});

test('overdueInvoices handles large number of invoices efficiently', () => {
  const invoices = [];
  for (let i = 0; i < 100; i++) {
    const inv = createInvoice({
      customerId: `C-${String((i % 10) + 1).padStart(3, '0')}`,
      issueDate: '2026-09-01',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    }).value;
    const issued = issueInvoice(inv, invoices.map(inv => inv.number || '')).value;
    invoices.push(issued);
  }

  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 100);
  // All should be overdue
  for (const inv of r) {
    assert.ok(inv.daysOverdue > 0);
  }
});

test('overdueInvoices returns results with all required fields', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  const result = r[0];
  assert.ok(result.hasOwnProperty('number'));
  assert.ok(result.hasOwnProperty('customerId'));
  assert.ok(result.hasOwnProperty('dueDate'));
  assert.ok(result.hasOwnProperty('daysOverdue'));
  assert.ok(result.hasOwnProperty('due'));
});

test('overdueInvoices does not mutate input invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const originalStatus = issued.status;
  const originalNumber = issued.number;

  const invoices = [issued];
  overdueInvoices(invoices, '2026-10-31');
  assert.equal(issued.status, originalStatus);
  assert.equal(issued.number, originalNumber);
});

